  --font-sans: Inter, sans-serif;
  --font-serif: Georgia, serif;
  --font-mono: Menlo, monospace;
  --radius: .5rem; /* 8px */
  --shadow-2xs: 0px 2px 0px 0px hsl(220 15% 85% / 0.05);
  --shadow-xs: 0px 2px 0px 0px hsl(220 15% 85% / 0.10);
  --shadow-sm: 0px 2px 0px 0px hsl(220 15% 85% / 0.10), 0px 1px 2px -1px hsl(220 15% 85% / 0.15);
  --shadow: 0px 2px 0px 0px hsl(220 15% 85% / 0.10), 0px 1px 2px -1px hsl(220 15% 85% / 0.15);
  --shadow-md: 0px 2px 0px 0px hsl(220 15% 85% / 0.10), 0px 2px 4px -1px hsl(220 15% 85% / 0.20);
