  --shadow-sm: 0px 2px 0px 0px hsl(220 15% 5% / 0.20), 0px 1px 2px -1px hsl(220 15% 5% / 0.25);
  --shadow: 0px 2px 0px 0px hsl(220 15% 5% / 0.20), 0px 1px 2px -1px hsl(220 15% 5% / 0.25);
  --shadow-md: 0px 2px 0px 0px hsl(220 15% 5% / 0.20), 0px 2px 4px -1px hsl(220 15% 5% / 0.30);
  --shadow-lg: 0px 2px 0px 0px hsl(220 15% 5% / 0.20), 0px 4px 6px -1px hsl(220 15% 5% / 0.35);
